beforeExample:
package test;

import org.eclipse.jdt.core.IJavaElement;
import org.eclipse.jdt.core.provisional.JavaModelAccess; // Provisional API

public class TestClass {
    public void method(IJavaElement element) throws Exception {
        // Provisional API usage
        JavaModelAccess.getAutomaticModuleDescription(element);
    }
}

afterExample:
package test;

import org.eclipse.jdt.core.IJavaElement;
import org.eclipse.jdt.core.JavaCore; // Final API

public class TestClass {
    public void method(IJavaElement element) throws Exception {
        // Final API usage
        JavaCore.getAutomaticModuleDescription(element);
    }
}

negativeExample:
package test;

import org.eclipse.jdt.core.IJavaElement;
import org.eclipse.jdt.core.JavaCore;

public class TestClass {
    public void method(IJavaElement element) throws Exception {
        // Already using final API
        JavaCore.getAutomaticModuleDescription(element);

        // Different method
        element.getJavaProject();
    }
}
